#include <iostream>
#include <map>
#include <string>
int main() {
    std::map<std::string, int> m;
    m["a"] = 1;
    int& r = m["b"];                 // operator[] 对不存在的 key 会插入（b=0）
    std::cout << "size=" << m.size() << '\n';
    try { m.at("z"); }
    catch (const std::out_of_range&) { std::cout << "at threw\n"; }
    std::cout << "b=" << r << '\n';
}
